import { getTasks, createTask, updateTask } from "wasp/client/operations";
import { logout } from "wasp/client/auth";
import { type AuthUser } from "wasp/auth";

type MainPageProps = {
  user: AuthUser;
};

export function MainPage({ user }: MainPageProps) {
  const { data: tasks, isLoading, error } = useQuery(getTasks);
  const createTaskFn = useAction(createTask);
  const updateTaskFn = useAction(updateTask);

  const [description, setDescription] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const trimmed = description.trim();
    if (!trimmed) return;

    setIsSubmitting(true);
    try {
      await createTaskFn({ description: trimmed });
      setDescription("");
    } catch (err) {
      console.error("Failed to create task:", err);
    } finally {
      setIsSubmitting(false);
    }
  }

  async function handleToggle(id: number, isDone: boolean) {
    try {
      await updateTaskFn({ id, isDone: !isDone });
    } catch (err) {
      console.error("Failed to update task:", err);
    }
  }

  const username =
    (user.identities.username as { id: string } | null)?.id ?? "User";

  return (
    <div className="app-container">
      <header className="app-header">
        <h1 className="app-title">📝 My Tasks</h1>
        <div className="header-right">
          <span className="username">👤 {username}</span>
          <button className="logout-btn" onClick={logout}>
            Logout
          </button>
        </div>
      </header>

      <main className="main-content">
        {/* Add task form */}
        <form className="add-task-form" onSubmit={handleSubmit}>
          <input
            className="task-input"
            type="text"
            placeholder="What needs to be done?"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            disabled={isSubmitting}
          />
          <button
            className="add-btn"
            type="submit"
            disabled={isSubmitting || !description.trim()}
          >
            {isSubmitting ? "Adding…" : "Add Task"}
          </button>
        </form>

        {/* Task list */}
        {isLoading && <p className="status-msg">Loading tasks…</p>}
        {error && (
          <p className="status-msg error">Error loading tasks: {error.message}</p>
        )}
        {tasks && tasks.length === 0 && (
          <p className="status-msg empty">
            No tasks yet — add one above!
          </p>
        )}
        {tasks && tasks.length > 0 && (
          <ul className="task-list">
            {tasks.map((task) => (
              <li
                key={task.id}
                className={`task-item ${task.isDone ? "done" : ""}`}
              >
                <label className="task-label">
                  <input
                    type="checkbox"
                    className="task-checkbox"
                    checked={task.isDone}
                    onChange={() => handleToggle(task.id, task.isDone)}
                  />
                  <span className="task-description">{task.description}</span>

