type MainPageProps = {
  user: AuthUser;
};

export function MainPage({ user }: MainPageProps) {
  const { data: tasks, isLoading, error } = useQuery(getTasks);
  const createTaskFn = useAction(createTask);
  const updateTaskFn = useAction(updateTask);

  const [description, setDescription] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const trimmed = description.trim();
    if (!trimmed) return;

    setIsSubmitting(true);
    try {
      await createTaskFn({ description: trimmed });
      setDescription("");
    } catch (err) {
      console.error("Failed to create task:", err);
    } finally {
      setIsSubmitting(false);
    }
  }

  async function handleToggle(id: number, isDone: boolean) {
    try {
      await updateTaskFn({ id, isDone: !isDone });
    } catch (err) {
      console.error("Failed to update task:", err);
    }
  }

  const username =
    (user.identities.username as { id: string } | null)?.id ?? "User";

  return (
    <div className="app-container">
      <header className="app-header">
        <h1 className="app-title">📝 My Tasks</h1>
        <div className="header-right">
          <span className="username">👤 {username}</span>
          <button className="logout-btn" onClick={logout}>
            Logout
          </button>
        </div>
      </header>

      <main className="main-content">
        {/* Add task form */}
        <form className="add-task-form" onSubmit={handleSubmit}>
          <input
            className="task-input"
            type="text"
            placeholder="What needs to be done?"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            disabled={isSubmitting}
          />
          <button
            className="add-btn"
            type="submit"
            disabled={isSubmitting || !description.trim()}
          >
            {isSubmitting ? "Adding…" : "Add Task"}
