}

.app-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: #2d3748;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.username {
  font-size: 0.875rem;
  color: #718096;
  font-weight: 500;
}

.logout-btn {
  background: #fed7d7;
  color: #c53030;
  border: none;
  border-radius: 8px;
